import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testFilterAndDoubleAbove50() {
        Assert.assertEquals(listOf(144, 182), filterAndDouble(listOf(45, 72, 38, 91), 50))
    }

    @Test
    fun testFilterAndDoubleAbove25() {
        Assert.assertEquals(listOf(60, 80), filterAndDouble(listOf(10, 20, 30, 40), 25))
    }

    @Test
    fun testAllFiltered() {
        Assert.assertEquals(emptyList<Int>(), filterAndDouble(listOf(10, 20), 50))
    }

    @Test
    fun testNoneFiltered() {
        Assert.assertEquals(listOf(20, 40, 60), filterAndDouble(listOf(10, 20, 30), 10))
    }

    @Test
    fun testEmptyList() {
        Assert.assertEquals(emptyList<Int>(), filterAndDouble(emptyList(), 0))
    }
}
